CREATE TABLE "ProfessionalDiligenceArtifact" ("id" TEXT NOT NULL,"diligenceReviewId" TEXT NOT NULL,"category" TEXT NOT NULL,"artifactHash" TEXT NOT NULL,"sourceUrl" TEXT NOT NULL,"professionalName" TEXT NOT NULL,"professionalRole" TEXT NOT NULL,"verifiedAt" TIMESTAMP(3) NOT NULL,"expiresAt" TIMESTAMP(3),"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ProfessionalDiligenceArtifact_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ProfessionalDiligenceArtifact_diligenceReviewId_category_artifactHash_key" ON "ProfessionalDiligenceArtifact"("diligenceReviewId","category","artifactHash");
CREATE INDEX "ProfessionalDiligenceArtifact_diligenceReviewId_category_verifiedAt_idx" ON "ProfessionalDiligenceArtifact"("diligenceReviewId","category","verifiedAt");
ALTER TABLE "ProfessionalDiligenceArtifact" ADD CONSTRAINT "ProfessionalDiligenceArtifact_diligenceReviewId_fkey" FOREIGN KEY ("diligenceReviewId") REFERENCES "DiligenceReview"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE OR REPLACE FUNCTION prevent_professional_diligence_artifact_mutation() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'Professional diligence artifacts are immutable'; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER "ProfessionalDiligenceArtifact_immutable" BEFORE UPDATE OR DELETE ON "ProfessionalDiligenceArtifact" FOR EACH ROW EXECUTE FUNCTION prevent_professional_diligence_artifact_mutation();
